//! R035/06 — UTF-8 validated source-range replace. Kernel-side implementation over actual RamFs/state.
use super::Error;
use crate::batch7_ramfs::{RamFs,CONTENT_MAX};
pub fn patch<const F:usize>(fs:&mut RamFs<F>,path:&[u8],revision:u64,start:usize,end:usize,insert:&[u8])->Result<u64,Error>{let(v,n)=fs.metadata(path).map_err(|_|Error::Missing)?;if v!=revision{return Err(Error::Stale);}let mut old=[0u8;CONTENT_MAX];fs.read(path,0,&mut old[..n]).map_err(|_|Error::Missing)?;let text=core::str::from_utf8(&old[..n]).map_err(|_|Error::Invalid)?;if start>end||end>n||!text.is_char_boundary(start)||!text.is_char_boundary(end)||core::str::from_utf8(insert).is_err(){return Err(Error::Invalid);}let size=n-(end-start)+insert.len();if size>CONTENT_MAX{return Err(Error::Full);}let mut next=[0u8;CONTENT_MAX];next[..start].copy_from_slice(&old[..start]);next[start..start+insert.len()].copy_from_slice(insert);next[start+insert.len()..size].copy_from_slice(&old[end..n]);fs.replace(path,&next[..size]).map_err(|_|Error::Full)}
#[cfg(test)]mod tests{use super::*;#[test]fn real_workflow_and_failure_guard(){let mut fs=RamFs::<1>::new();fs.replace(b"/p/a","aβc".as_bytes()).unwrap();patch(&mut fs,b"/p/a",1,1,3,b"XYZ").unwrap();let mut v=[0;5];fs.read(b"/p/a",0,&mut v).unwrap();assert_eq!(&v,b"aXYZc");}}
